<script setup lang="ts">import {ref} from 'vue';import type {Workspace} from '../stores/workspace';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import {create,acknowledge} from '../api/scenarios';import {create as run} from '../api/runs';import {useAsync} from '../hooks/useAsync';const props=defineProps<{data:Workspace;canWrite:boolean;refresh:()=>Promise<void>}>();const emit=defineEmits<{go:[string]}>();const name=ref(''),profile=ref(''),windows=ref(3),arrival=ref(1),service=ref(1),duration=ref(480),warmup=ref(120),reps=ref(30),seed=ref(2206);const {busy,error,execute}=useAsync();const profileOf=(id:string)=>props.data.profiles.find(p=>p.id===id);async function submit(){await execute(async()=>{await create({name:name.value,profile_id:profile.value||props.data.profiles[0]?.id,windows:windows.value,arrival_multiplier:arrival.value,service_multiplier:service.value,duration_minutes:duration.value,warmup_minutes:warmup.value,replications:reps.value,seed:seed.value});name.value='';await props.refresh()})}async function launch(id:string){await execute(async()=>{await run({scenario_id:id});await props.refresh();emit('go','results')})}async function confirm(id:string){await execute(async()=>{await acknowledge(id);await props.refresh()})};
</script><template><PageHeading code="04 / COUNTER SCENARIOS" title="窗口数之外，把假设也写下来。" description="到达倍率作用于λ，服务倍率作用于单窗口μ。源观测更新后方案标记失效，确认新剖面后才能再次运行。"/><section v-if="canWrite" class="paper"><h2>新建窗口预演</h2><form class="scenario-form" @submit.prevent="submit"><label>方案名称<input aria-label="方案名称" v-model="name" required minlength="2"/></label><label>输入剖面<select aria-label="输入剖面" v-model="profile"><option value="" disabled>默认使用最新剖面</option><option v-for="p in data.profiles" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>窗口数 c<input aria-label="窗口数" type="number" min="1" max="12" v-model.number="windows"/></label><label>到达倍率<input type="number" min=".2" max="3" step=".1" v-model.number="arrival"/></label><label>服务倍率<input type="number" min=".2" max="3" step=".1" v-model.number="service"/></label><label>观测时域 / 分钟<input type="number" min="60" max="1440" v-model.number="duration"/></label><label>预热 / 分钟<input type="number" min="0" max="1440" v-model.number="warmup"/></label><label>重复次数<input aria-label="重复次数" type="number" min="5" max="100" v-model.number="reps"/></label><label>随机种子<input type="number" min="0" v-model.number="seed"/></label><button :disabled="busy">保存窗口方案</button></form></section><Notice v-if="error" error>{{error}}</Notice><section class="paper"><h2>已保存方案</h2><article v-for="s in data.scenarios" :key="s.id" class="scenario-row"><div class="counter-number">{{s.windows}}<small>WINDOWS</small></div><div class="scenario-detail"><h3>{{s.name}} <span v-if="s.stale" class="status failed">已失效</span></h3><p>{{profileOf(s.profile_id)?.name}}<template v-if="profileOf(s.profile_id)?.stale"> · 剖面重算失败，保留上次可用结果</template></p><small>观测{{s.duration_minutes}}分钟 · 预热{{s.warmup_minutes}}分钟 · {{s.replications}}次重复 · seed {{s.seed}}</small><small v-if="s.stale" class="stale-reason">{{s.stale_reason}}</small></div><template v-if="canWrite"><button v-if="s.stale" class="secondary" :disabled="busy||!!profileOf(s.profile_id)?.stale" @click="confirm(s.id)">确认新剖面　✓</button><button class="secondary" :disabled="busy||!!s.stale||!!profileOf(s.profile_id)?.stale" @click="launch(s.id)">运行预演　→</button></template></article></section><section class="paper"><h2>运行队列</h2><div class="table-scroll"><table><thead><tr><th>窗口方案</th><th>状态</th><th>提交时间</th></tr></thead><tbody><tr v-for="r in data.runs" :key="r.id"><td>{{data.scenarios.find(s=>s.id===r.scenario_id)?.name}}</td><td><Status :value="r.status"/></td><td>{{r.created_at.slice(0,19).replace('T',' ')}}</td></tr></tbody></table></div></section></template>
